// ---------- EDIT THIS BLOCK ----------
const DEPOT = { label: 'Shop / depot', lat: 44.9778, lng: -93.265 };
const TIMEZONE = 'America/Chicago';
const DAY_START = '07:30';          // when the technician leaves the depot
const DAY_END = '17:00';            // end of the paid day
const DEFAULT_VISIT_MINUTES = 60;   // used when the sheet leaves duration blank
const BUFFER_MINUTES = 10;          // parking, walking to the door, paperwork
const RETURN_TO_DEPOT = true;       // count the drive home in the day length
const MAX_STOPS = 24;               // the public OSRM demo server caps matrix size
const AVERAGE_SPEED_KMH = 35;       // fallback only, if OSRM cannot be reached
const ROAD_FACTOR = 1.3;            // straight line -> road distance, fallback only
// -------------------------------------

function todayInZone(zone) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: zone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(new Date());
  const get = (type) => parts.find((p) => p.type === type).value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

const today = todayInZone(TIMEZONE);
const stops = [];
const skipped = [];
const seen = new Set();

for (const item of $input.all()) {
  // Spreadsheet headers often carry stray spaces, so normalise them before reading.
  const row = {};
  for (const [key, value] of Object.entries(item.json)) row[String(key).trim()] = value;

  const visitId = String(row.visit_id ?? '').trim();
  if (!visitId) continue;

  const visitDate = String(row.visit_date ?? '').trim().slice(0, 10);
  if (visitDate && visitDate !== today) continue;

  const status = String(row.status ?? '').trim().toLowerCase();
  if (status === 'done' || status === 'cancelled' || status === 'canceled') continue;

  if (seen.has(visitId)) continue;
  seen.add(visitId);

  const lat = Number(row.lat);
  const lng = Number(row.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng) || (lat === 0 && lng === 0)) {
    skipped.push({ visit_id: visitId, reason: 'latitude or longitude is missing or not a number' });
    continue;
  }

  const minutes = Number(row.duration_minutes);
  const pinRaw = String(row.pin ?? '').trim().toLowerCase();

  stops.push({
    visit_id: visitId,
    customer: String(row.customer ?? '').trim() || visitId,
    address: String(row.address ?? '').trim(),
    phone: String(row.phone ?? '').trim(),
    job: String(row.job ?? '').trim(),
    lat,
    lng,
    visit_minutes: Number.isFinite(minutes) && minutes > 0 ? minutes : DEFAULT_VISIT_MINUTES,
    pin: pinRaw === 'first' || pinRaw === 'last' ? pinRaw : '',
  });
}

// The demo routing server refuses very large matrices, so keep the day inside the cap.
if (stops.length > MAX_STOPS) {
  for (const extra of stops.slice(MAX_STOPS)) {
    skipped.push({ visit_id: extra.visit_id, reason: `beyond the ${MAX_STOPS} stop matrix limit` });
  }
  stops.length = MAX_STOPS;
}

// Nothing to plan: end this branch quietly instead of emailing an empty route.
if (stops.length === 0) return [];

const points = [DEPOT, ...stops];
const coordinates = points.map((p) => `${p.lng},${p.lat}`).join(';');

return [
  {
    json: {
      route_date: today,
      depot: DEPOT,
      stops,
      skipped,
      config: {
        timezone: TIMEZONE,
        day_start: DAY_START,
        day_end: DAY_END,
        buffer_minutes: BUFFER_MINUTES,
        return_to_depot: RETURN_TO_DEPOT,
        average_speed_kmh: AVERAGE_SPEED_KMH,
        road_factor: ROAD_FACTOR,
      },
      osrm_url: `https://router.project-osrm.org/table/v1/driving/${coordinates}?annotations=duration`,
    },
  },
];

// Turn the routing response into a square matrix of drive times in minutes.
// If the routing service is unavailable the workflow keeps going on estimates
// rather than failing, because a rough order still beats no order at all.
const prep = $('Prepare Stops').first().json;
const points = [prep.depot, ...prep.stops];
const size = points.length;
const response = $input.first().json ?? {};

function straightLineMinutes(a, b) {
  const EARTH_KM = 6371;
  const rad = (deg) => (deg * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  const km = 2 * EARTH_KM * Math.asin(Math.min(1, Math.sqrt(h))) * prep.config.road_factor;
  return (km / prep.config.average_speed_kmh) * 60;
}

function isUsable(durations) {
  return (
    Array.isArray(durations) &&
    durations.length === size &&
    durations.every(
      (row) =>
        Array.isArray(row) &&
        row.length === size &&
        row.every((value) => typeof value === 'number' && Number.isFinite(value)),
    )
  );
}

const round = (value) => Math.round(value * 10) / 10;

let matrix;
let source;
let note;

if (response.code === 'Ok' && isUsable(response.durations)) {
  matrix = response.durations.map((row) => row.map((seconds) => round(seconds / 60)));
  source = 'routing service';
  note = 'Drive times are real road times from the OSRM routing service.';
} else {
  matrix = points.map((from) => points.map((to) => round(straightLineMinutes(from, to))));
  source = 'estimate';
  const reason =
    response.code && response.code !== 'Ok'
      ? `the service replied ${response.code}`
      : response.code === 'Ok'
        ? 'the matrix came back the wrong shape'
        : response.message || 'the service did not answer';
  note = `Real drive times were unavailable (${reason}), so the plan uses straight-line estimates at ${prep.config.average_speed_kmh} km/h. The order is still sensible, but treat the arrival times as rough.`;
}

for (let i = 0; i < size; i++) matrix[i][i] = 0;

return [{ json: { ...prep, matrix, matrix_source: source, matrix_note: note } }];

// Two-stage route optimisation over the drive-time matrix.
//   Stage 1 - nearest neighbour: start at the depot and always hop to the
//             closest stop that has not been visited yet. Fast, but it tends
//             to leave one long stretch at the end.
//   Stage 2 - 2-opt: repeatedly reverse a slice of the route and keep the
//             reversal whenever it shortens the total drive. This untangles
//             the crossings nearest neighbour leaves behind.
// Stops marked 'first' or 'last' in the sheet are locked in place, so an
// 8 a.m. commitment or an end-of-day drop-off is never shuffled away.
const data = $input.first().json;
const matrix = data.matrix;
const stops = data.stops;
const returnToDepot = data.config.return_to_depot;

const DEPOT = 0;
const point = (stopIndex) => stopIndex + 1;

function driveTotal(sequence) {
  let total = 0;
  let cursor = DEPOT;
  for (const stopIndex of sequence) {
    total += matrix[cursor][point(stopIndex)];
    cursor = point(stopIndex);
  }
  if (returnToDepot) total += matrix[cursor][DEPOT];
  return Math.round(total * 10) / 10;
}

const lockedFirst = [];
const lockedLast = [];
const movable = [];
stops.forEach((stop, index) => {
  if (stop.pin === 'first') lockedFirst.push(index);
  else if (stop.pin === 'last') lockedLast.push(index);
  else movable.push(index);
});

const sheetOrder = [...lockedFirst, ...movable, ...lockedLast];
const sheetOrderMinutes = driveTotal(sheetOrder);

// ---------- Stage 1: nearest neighbour ----------
let cursor = lockedFirst.length ? point(lockedFirst[lockedFirst.length - 1]) : DEPOT;
const pool = [...movable];
const greedy = [];
while (pool.length) {
  let bestAt = 0;
  let bestDrive = Infinity;
  for (let i = 0; i < pool.length; i++) {
    const drive = matrix[cursor][point(pool[i])];
    if (drive < bestDrive) {
      bestDrive = drive;
      bestAt = i;
    }
  }
  const chosen = pool.splice(bestAt, 1)[0];
  greedy.push(chosen);
  cursor = point(chosen);
}

let sequence = [...lockedFirst, ...greedy, ...lockedLast];
const greedyMinutes = driveTotal(sequence);

// ---------- Stage 2: 2-opt on the movable middle ----------
const low = lockedFirst.length;
const high = sequence.length - lockedLast.length - 1;
let bestMinutes = greedyMinutes;
let passes = 0;
let improving = high > low;

while (improving && passes < 100) {
  improving = false;
  passes++;
  for (let i = low; i < high; i++) {
    for (let k = i + 1; k <= high; k++) {
      const candidate = sequence
        .slice(0, i)
        .concat(sequence.slice(i, k + 1).reverse(), sequence.slice(k + 1));
      const candidateMinutes = driveTotal(candidate);
      if (candidateMinutes < bestMinutes - 0.05) {
        sequence = candidate;
        bestMinutes = candidateMinutes;
        improving = true;
      }
    }
  }
}

const ordered = sequence.map((stopIndex, position) => {
  const from = position === 0 ? DEPOT : point(sequence[position - 1]);
  return {
    ...stops[stopIndex],
    sequence: position + 1,
    drive_minutes: matrix[from][point(stopIndex)],
    drive_from: position === 0 ? data.depot.label : stops[sequence[position - 1]].customer,
  };
});

const driveHome = returnToDepot
  ? matrix[point(sequence[sequence.length - 1])][DEPOT]
  : 0;

return [
  {
    json: {
      ...data,
      ordered,
      drive_home_minutes: driveHome,
      optimisation: {
        stops: stops.length,
        locked: lockedFirst.length + lockedLast.length,
        sheet_order_minutes: sheetOrderMinutes,
        nearest_neighbour_minutes: greedyMinutes,
        optimised_minutes: bestMinutes,
        saved_minutes: Math.round((sheetOrderMinutes - bestMinutes) * 10) / 10,
        two_opt_passes: passes,
      },
    },
  },
];

// Walk the optimised order forwards from the start of the day and give every
// stop a real arrival time: previous departure + drive + buffer. Anything that
// lands after the end of the paid day is flagged so dispatch can move it now
// instead of apologising this afternoon.
const data = $input.first().json;
const config = data.config;
const zone = config.timezone;

function offsetMinutes(instant) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: zone,
    hour12: false,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  }).formatToParts(instant);
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  const asUTC = Date.UTC(
    get('year'),
    get('month') - 1,
    get('day'),
    get('hour') % 24,
    get('minute'),
    get('second'),
  );
  return (asUTC - instant.getTime()) / 60000;
}

// Two passes, so the conversion stays correct on the days the clocks change.
function localToInstant(dateText, timeText) {
  const [year, month, day] = dateText.split('-').map(Number);
  const [hour, minute] = timeText.split(':').map(Number);
  const naive = Date.UTC(year, month - 1, day, hour, minute);
  let guess = naive;
  for (let pass = 0; pass < 2; pass++) {
    guess = naive - offsetMinutes(new Date(guess)) * 60000;
  }
  return guess;
}

const clock = (instant) =>
  new Intl.DateTimeFormat('en-US', {
    timeZone: zone,
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).format(new Date(instant));

const dayStart = localToInstant(data.route_date, config.day_start);
const dayEnd = localToInstant(data.route_date, config.day_end);

let cursor = dayStart;
let driveMinutes = 0;
let onSiteMinutes = 0;
const route = [];
const lateStops = [];

for (const stop of data.ordered) {
  const arrive = cursor + stop.drive_minutes * 60000;
  const leave = arrive + (stop.visit_minutes + config.buffer_minutes) * 60000;
  const late = leave > dayEnd;

  driveMinutes += stop.drive_minutes;
  onSiteMinutes += stop.visit_minutes + config.buffer_minutes;

  route.push({
    route_date: data.route_date,
    visit_id: stop.visit_id,
    sequence: stop.sequence,
    customer: stop.customer,
    address: stop.address,
    phone: stop.phone,
    job: stop.job,
    eta: clock(arrive),
    depart: clock(leave),
    drive_minutes: stop.drive_minutes,
    drive_from: stop.drive_from,
    visit_minutes: stop.visit_minutes,
    pin: stop.pin,
    past_end_of_day: late,
    drive_times: data.matrix_source,
  });

  if (late) lateStops.push(stop.customer || stop.visit_id);
  cursor = leave;
}

const finish = cursor + data.drive_home_minutes * 60000;
const overrunMinutes = Math.max(0, Math.round((finish - dayEnd) / 60000));

const summary = {
  route_date: data.route_date,
  stops: route.length,
  skipped: data.skipped.length,
  leave_depot: clock(dayStart),
  back_at_depot: clock(finish),
  drive_minutes: Math.round(driveMinutes + data.drive_home_minutes),
  on_site_minutes: Math.round(onSiteMinutes),
  saved_minutes: data.optimisation.saved_minutes,
  overrun_minutes: overrunMinutes,
  late_stops: lateStops,
  drive_times: data.matrix_source,
};

const esc = (text) =>
  String(text ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

const lines = route.map(
  (stop) =>
    `<tr><td style="padding:6px 10px;border-bottom:1px solid #e5e5e5">${stop.sequence}</td>` +
    `<td style="padding:6px 10px;border-bottom:1px solid #e5e5e5"><strong>${esc(stop.eta)}</strong></td>` +
    `<td style="padding:6px 10px;border-bottom:1px solid #e5e5e5">${esc(stop.customer)}<br><span style="color:#666">${esc(stop.address)}</span></td>` +
    `<td style="padding:6px 10px;border-bottom:1px solid #e5e5e5">${esc(stop.job)}</td>` +
    `<td style="padding:6px 10px;border-bottom:1px solid #e5e5e5">${stop.drive_minutes} min</td></tr>`,
);

const html =
  `<div style="font-family:Arial,Helvetica,sans-serif;font-size:14px;color:#222">` +
  `<h2 style="margin:0 0 4px">Route for ${esc(data.route_date)}</h2>` +
  `<p style="margin:0 0 16px;color:#666">${summary.stops} stops · leave ${esc(summary.leave_depot)} · back ${esc(summary.back_at_depot)} · ${summary.drive_minutes} min driving</p>` +
  `<table style="border-collapse:collapse;width:100%"><thead><tr>` +
  `<th align="left" style="padding:6px 10px;border-bottom:2px solid #222">#</th>` +
  `<th align="left" style="padding:6px 10px;border-bottom:2px solid #222">ETA</th>` +
  `<th align="left" style="padding:6px 10px;border-bottom:2px solid #222">Customer</th>` +
  `<th align="left" style="padding:6px 10px;border-bottom:2px solid #222">Job</th>` +
  `<th align="left" style="padding:6px 10px;border-bottom:2px solid #222">Drive</th>` +
  `</tr></thead><tbody>${lines.join('')}</tbody></table>` +
  (summary.saved_minutes > 0
    ? `<p style="margin:16px 0 0;color:#166534">This order saves about ${summary.saved_minutes} minutes of driving compared with the order on the sheet.</p>`
    : '') +
  (overrunMinutes > 0
    ? `<p style="margin:8px 0 0;color:#991b1b">The day runs ${overrunMinutes} minutes past ${esc(config.day_end)}. Late: ${esc(lateStops.join(', '))}.</p>`
    : '') +
  (data.skipped.length
    ? `<p style="margin:8px 0 0;color:#991b1b">Left off the route: ${esc(data.skipped.map((s) => `${s.visit_id} (${s.reason})`).join('; '))}.</p>`
    : '') +
  `<p style="margin:16px 0 0;color:#888;font-size:12px">${esc(data.matrix_note)}</p></div>`;

const alert =
  `<b>Route overruns ${esc(config.day_end)}</b>\n` +
  `${esc(data.route_date)} · ${summary.stops} stops\n` +
  `Back at the depot ${esc(summary.back_at_depot)} (${overrunMinutes} min over)\n` +
  `Driving ${summary.drive_minutes} min · on site ${summary.on_site_minutes} min\n` +
  (lateStops.length ? `Past end of day: ${esc(lateStops.join(', '))}\n` : '') +
  (data.skipped.length
    ? `No coordinates: ${esc(data.skipped.map((s) => s.visit_id).join(', '))}\n`
    : '') +
  `Move or reschedule one visit to bring the day back inside hours.`;

return [{ json: { summary, route, email_html: html, alert_html: alert } }];
